    if (n == 0) return 0;
    return a[0] + sum_recursive(a + 1, n - 1);
}

int sum_iterative(int *a, int n) {
    int total = 0;
    for (int i = 0; i < n; ++i) {
        total += a[i];
    }
    return total;
}
```

